def mode_to_text(mode):
    if type(mode) is not int:
        raise ValueError("mode must be an integer")
    if not (0 <= mode <= 0o7777):
        raise ValueError("mode out of range")
    result = []
    triples = [
        (0o400, 0o200, 0o100, 0o4000),
        (0o040, 0o020, 0o010, 0o2000),
        (0o004, 0o002, 0o001, 0o1000),
    ]
    for r_mask, w_mask, x_mask, special_mask in triples:
        has_read = bool(mode & r_mask)
        has_write = bool(mode & w_mask)
        has_execute = bool(mode & x_mask)
        has_special = bool(mode & special_mask)

        r_char = 'r' if has_read else '-'
        w_char = 'w' if has_write else '-'

        if has_special:
            if special_mask in (0o4000, 0o2000):
                x_char = 's' if has_execute else 'S'
            else:
                x_char = 't' if has_execute else 'T'
        else:
            x_char = 'x' if has_execute else '-'

        result.append(r_char + w_char + x_char)
    return ''.join(result)

def text_to_mode(text):
    if type(text) is not str:
        raise ValueError("text must be a string")
    if len(text) != 9:
        raise ValueError("text must be exactly 9 characters")
    mode = 0
    # Check each character's validity and compute mode
    for i in range(3):
        # owner, group, others
        triple = text[i*3:(i+1)*3]
        r_char, w_char, x_char = triple
        # Check validity of each character
        if i in (0, 1, 2):
            if i in (0, 1):
                valid_third = {'x', '-', 's', 'S'}
            else:
                valid_third = {'x', '-', 't', 'T'}
            if r_char not in {'r', '-'} or w_char not in {'w', '-'} or x_char not in valid_third:
                raise ValueError("invalid character in text")
        # Determine read, write, execute bits
        read = 1 if r_char == 'r' else 0
        write = 1 if w_char == 'w' else 0
        # Determine execute and special bit
        if i == 0:  # owner
            if x_char == 'x':
                execute = 1
                special = 0
            elif x_char == '-':
                execute = 0
                special = 0
            elif x_char == 's':
                execute = 1
                special = 1
            elif x_char == 'S':
                execute = 0
                special = 1
            else:
                raise ValueError("invalid character")
        elif i == 1:  # group
            if x_char == 'x':
                execute = 1
                special = 0
            elif x_char == '-':
                execute = 0
                special = 0
            elif x_char == 's':
                execute = 1
                special = 1
            elif x_char == 'S':
                execute = 0
                special = 1
            else:
                raise ValueError("invalid character")
        else:  # others
            if x_char == 'x':
                execute = 1
                special = 0
            elif x_char == '-':
                execute = 0
                special = 0
            elif x_char == 't':
                execute = 1
                special = 1
            elif x_char == 'T':
                execute = 0
                special = 1
            else:
                raise ValueError("invalid character")
        # Set standard bits
        if i == 0:
            r_mask, w_mask, x_mask = 0o400, 0o200, 0o100
        elif i == 1:
            r_mask, w_mask, x_mask = 0o040, 0o020, 0o010
        else:
            r_mask, w_mask, x_mask = 0o004, 0o002, 0o001
        mode |= (read * r_mask)
        mode |= (write * w_mask)
        mode |= (execute * x_mask)
        # Set special bit
        if i == 0 and special:
            mode |= 0o4000
        elif i == 1 and special:
            mode |= 0o2000
        elif i == 2 and special:
            mode |= 0o1000
    return mode

def format_size(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 0:
        raise ValueError
    if n == 0:
        return "0 B"
    if n < 1024:
        return f"{n} B"
    units = [('KiB', 1024**1), ('MiB', 1024**2), ('GiB', 1024**3), ('TiB', 1024**4), ('PiB', 1024**5)]
    selected_unit = None
    for i in reversed(range(len(units))):
        if units[i][1] <= n:
            selected_unit = units[i]
            break
    unit_name, unit_value = selected_unit
    numerator = n * 10
    tenths = numerator // unit_value
    remainder = numerator % unit_value
    if remainder * 2 >= unit_value:
        tenths += 1
    if tenths == 10240 and i < len(units) - 1:
        return "1.0 " + units[i + 1][0]
    integer_part = tenths // 10
    decimal_part = tenths % 10
    if decimal_part == 0:
        return f"{integer_part}.0 {unit_name}"
    else:
        return f"{integer_part}.{decimal_part} {unit_name}"

