def expand_tabs(line, width):
    if not isinstance(line, str):
        raise ValueError("line must be a string")
    if '\n' in line or '\r' in line:
        raise ValueError("line contains newline or carriage return")
    if not isinstance(width, int) or isinstance(width, bool):
        raise ValueError("width must be an integer between 1 and 32")
    if not (1 <= width <= 32):
        raise ValueError("width must be between 1 and 32")
    current_col = 0
    result = []
    for c in line:
        if c == '\t':
            next_stop = (current_col // width + 1) * width
            num_spaces = next_stop - current_col
            result.append(' ' * num_spaces)
            current_col = next_stop
        else:
            result.append(c)
            current_col += 1
    return ''.join(result)

def collapse_spaces(line, width):
    if not isinstance(line, str):
        raise ValueError("line must be a string")
    if '\n' in line or '\r' in line:
        raise ValueError("line contains newline or carriage return")
    if '\t' in line:
        raise ValueError("line contains tabs")
    if not isinstance(width, int) or isinstance(width, bool):
        raise ValueError("width must be an integer between 1 and 32")
    if not (1 <= width <= 32):
        raise ValueError("width must be between 1 and 32")
    n = len(line)
    num_full = n // width
    chunks = []
    for i in range(num_full):
        chunk = line[i*width : (i+1)*width]
        trail = 0
        for c in reversed(chunk):
            if c == ' ':
                trail += 1
            else:
                break
        if trail >= 2:
            chunks.append(chunk[:-trail] + '\t')
        else:
            chunks.append(chunk)
    last_chunk = line[num_full * width:]
    return ''.join(chunks) + last_chunk

def qp_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError
    tokens = []
    length = len(data)
    for i in range(length):
        byte = data[i]
        if 33 <= byte <= 126 and byte != 61:
            tokens.append(chr(byte))
        elif byte == 32:
            if i == length - 1:
                tokens.append("=20")
            else:
                tokens.append(" ")
        else:
            tokens.append("={:02X}".format(byte))
    output_lines = []
    current_line = []
    current_length = 0
    for idx, token in enumerate(tokens):
        is_last = (idx == len(tokens) - 1)
        token_len = len(token)
        if not current_line:
            current_line.append(token)
            current_length = token_len
        else:
            proposed_length = current_length + token_len
            allowed_length = 75 if not is_last else 76
            if proposed_length <= allowed_length:
                current_line.append(token)
                current_length += token_len
            else:
                output_lines.append(''.join(current_line))
                current_line = [token]
                current_length = token_len
    if current_line:
        output_lines.append(''.join(current_line))
    if not output_lines:
        return ""
    return '=\r\n'.join(output_lines)

def qp_decode(text):
    if not isinstance(text, str):
        raise ValueError
    text = text.replace("=\r\n", "")
    result = bytearray()
    index = 0
    while index < len(text):
        if text[index] == '=':
            if index + 2 >= len(text):
                raise ValueError
            hex_part = text[index+1:index+3]
            if not (hex_part[0].upper() in '0123456789ABCDEF' and hex_part[1].upper() in '0123456789ABCDEF'):
                raise ValueError
            try:
                byte = int(hex_part, 16)
            except ValueError:
                raise ValueError
            result.append(byte)
            index += 3
        else:
            c = text[index]
            if ord(c) >= 128:
                raise ValueError
            if ord(c) < 32 or ord(c) == 61:
                raise ValueError
            result.append(ord(c))
            index += 1
    return bytes(result)

