def parse_params(value):
    value = value.strip(' \t')
    if not value:
        raise ValueError("empty value")

    # Parse media type
    semicolon_pos = value.find(';')
    media_type_part = value[:semicolon_pos] if semicolon_pos != -1 else value
    media_type_part_stripped = media_type_part.strip(' \t')

    slash_pos = media_type_part_stripped.find('/')
    if slash_pos == -1 or slash_pos == 0 or slash_pos == len(media_type_part_stripped) - 1:
        raise ValueError("invalid media type")

    type_part = media_type_part_stripped[:slash_pos]
    subtype_part = media_type_part_stripped[slash_pos+1:]
    if '/' in subtype_part:
        raise ValueError("invalid media type")

    if not is_valid_token(type_part) or not is_valid_token(subtype_part):
        raise ValueError("invalid media type token")

    media_type = (type_part + '/' + subtype_part).lower()

    params = {}
    if semicolon_pos != -1:
        params_part = value[semicolon_pos:]
        parts = []
        current = []
        inquote = False
        escape = False
        for c in params_part:
            if escape:
                current.append(c)
                escape = False
                continue
            if c == '\\':
                escape = True
                current.append(c)
                continue
            if c == '"':
                inquote = not inquote
            if c == ';' and not inquote:
                parts.append(''.join(current))
                current = []
            else:
                current.append(c)
        if current:
            parts.append(''.join(current))
        for part in parts:
            part = part.strip(' \t')
            if not part:
                continue
            if '=' not in part:
                raise ValueError("parameter missing =")
            equal_pos = part.find('=')
            if equal_pos == 0:
                raise ValueError("empty parameter name")
            name = part[:equal_pos]
            value_part = part[equal_pos+1:]
            if not value_part:
                raise ValueError("empty parameter value")

            if not is_valid_token(name):
                raise ValueError("invalid parameter name")

            lower_name = name.lower()
            if lower_name in params:
                raise ValueError("duplicate parameter name")

            if value_part.startswith('"') and value_part.endswith('"'):
                try:
                    val = parse_quoted_string(value_part)
                except ValueError:
                    raise ValueError("invalid quoted string")
            else:
                if not is_valid_token(value_part):
                    raise ValueError("invalid parameter value")
                val = value_part

            params[lower_name] = val

    return (media_type, params)

def parse_quoted_string(s):
    if len(s) < 2 or s[0] != '"' or s[-1] != '"':
        raise ValueError("invalid quoted string")
    inner = s[1:-1]
    result = []
    i = 0
    while i < len(inner):
        if inner[i] == '\\':
            if i + 1 >= len(inner):
                raise ValueError("unterminated quoted string")
            result.append(inner[i + 1])
            i += 2
        else:
            c = inner[i]
            if ord(c) < 32 or ord(c) == 127:
                raise ValueError("control character in quoted string")
            result.append(c)
            i += 1
    return ''.join(result)

