def zeckendorf(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    upper = 10**30
    if n < 0 or n > upper:
        raise ValueError
    if n == 0:
        return []
    a, b = 1, 2
    fibs = []
    while a <= n:
        fibs.append(a)
        a, b = b, a + b
    current = n
    result = []
    i = len(fibs) - 1
    while current > 0 and i >= 0:
        if fibs[i] <= current:
            result.append(fibs[i])
            current -= fibs[i]
            i -= 2
        else:
            i -= 1
    return result

def fib_code(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    upper = 10**30
    if n < 1 or n > upper:
        raise ValueError
    a, b = 1, 2
    fibs = []
    while a <= n:
        fibs.append(a)
        a, b = b, a + b
    zek_list = zeckendorf(n)
    zek_set = set(zek_list)
    bits = []
    for fib in fibs:
        bits.append('1' if fib in zek_set else '0')
    code_str = ''.join(bits) + '1'
    return code_str

def fib_decode(bits):
    if not isinstance(bits, str):
        raise ValueError
    if not all(c in '01' for c in bits):
        raise ValueError
    if bits == "":
        return []
    i = 0
    result = []
    while i < len(bits):
        pos = bits.find('11', i)
        if pos == -1:
            raise ValueError
        code = bits[i:pos + 2]
        # Compute the value from code
        # code is a string of 0s and 1s (without the final '11'?), no: code includes '11' at the end
        # The code is the bits up to the last '11' (the last '1' is part of the code)
        # So the code is the string up to and including the '11', but the last '1' is part of the Zeckendorf representation
        # So we need to process code[:-1] and then check that the last two are '11'
        if len(code) < 2 or code[-2:] != '11':
            raise ValueError
        code_bits = code[:-1]  # remove the final '1'
        if not code_bits:
            # code was '11', so code_bits is empty, which corresponds to the first Fibonacci number (1)
            result.append(1)
        else:
            # Generate Fibonacci numbers up to the needed count
            fibs = []
            a, b = 1, 2
            for j in range(len(code_bits)):
                if j >= len(fibs):
                    fibs.append(a)
                    a, b = b, a + b
                else:
                    pass  # already generated
            total = 0
            for idx, bit in enumerate(code_bits):
                if bit == '1':
                    total += fibs[idx]
            result.append(total)
        i = pos + 2
    if i != len(bits):
        raise ValueError
    return result

import math

def aliquot_chain(n, limit):
    if type(n) is not int or type(limit) is not int:
        raise ValueError()
    if not (1 <= n <= 10**6):
        raise ValueError()
    if not (1 <= limit <= 1000):
        raise ValueError()
    terms = [n]
    for _ in range(limit):
        last = terms[-1]
        m = last
        if m == 1:
            s_last = 0
        else:
            s_last = 0
            sqrt_m = int(math.sqrt(m))
            for i in range(1, sqrt_m + 1):
                if m % i == 0:
                    if i != m:
                        s_last += i
                    other = m // i
                    if other != i and other != m:
                        s_last += other
        if s_last == 0:
            terms.append(0)
            return ('terminates', terms)
        if s_last in terms:
            i = terms.index(s_last)
            L = len(terms) - i
            if i == 0:
                if L == 1:
                    kind = 'perfect'
                elif L == 2:
                    kind = 'amicable'
                else:
                    kind = 'sociable'
            else:
                if L == 1:
                    kind = 'aspiring'
                else:
                    kind = 'cyclic'
            return (kind, terms)
        else:
            if s_last > 10**9:
                return ('unknown', terms)
            else:
                terms.append(s_last)
    return ('unknown', terms)

import math

def is_prime_power(m):
    if m == 1:
        return False
    for i in range(2, int(math.isqrt(m)) + 1):
        if m % i == 0:
            temp = m
            while temp % i == 0:
                temp //= i
            if temp == 1:
                return True
            else:
                return False
    return True

def has_primitive_root(n):
    if n == 2 or n == 4:
        return True
    if n % 2 == 0:
        if (n & (n - 1)) == 0:
            return False
        m = n // 2
        if m % 2 == 1 and is_prime_power(m):
            return True
        else:
            return False
    else:
        return is_prime_power(n)

def compute_phi(m):
    if m == 1:
        return 1
    phi = m
    i = 2
    while i * i <= m:
        if m % i == 0:
            while m % i == 0:
                m //= i
            phi -= phi // i
        i += 1
    if m > 1:
        phi -= phi // m
    return phi

def prime_factors(m):
    factors = set()
    if m % 2 == 0:
        factors.add(2)
        while m % 2 == 0:
            m //= 2
    i = 3
    while i * i <= m:
        if m % i == 0:
            factors.add(i)
            while m % i == 0:
                m //= i
        i += 2
    if m > 1:
        factors.add(m)
    return factors

def smallest_primitive_root(n):
    if not isinstance(n, int):
        raise ValueError
    if n < 2 or n > 10**10:
        raise ValueError
    if not has_primitive_root(n):
