def trailing_zeros(n, b):
    if type(n) is not int:
        raise ValueError
    if type(b) is not int:
        raise ValueError
    if n < 0 or n > 10**18:
        raise ValueError
    if b < 2 or b > 10**6:
        raise ValueError

    factors = {}
    m = b
    i = 2
    while i * i <= m:
        while m % i == 0:
            factors[i] = factors.get(i, 0) + 1
            m = m // i
        i += 1
    if m > 1:
        factors[m] = 1

    min_z = float('inf')
    for p, e in factors.items():
        current_p = p
        exp = 0
        while current_p <= n:
            exp += n // current_p
            current_p *= p
        z = exp // e
        if z < min_z:
            min_z = z
    return min_z if min_z != float('inf') else 0

def binomial_zeros(n, k, b):
    if type(n) is not int:
        raise ValueError
    if type(k) is not int:
        raise ValueError
    if type(b) is not int:
        raise ValueError
    if n < 0 or n > 10**18:
        raise ValueError
    if k < 0 or k > n:
        raise ValueError
    if b < 2 or b > 10**6:
        raise ValueError

    factors = {}
    m = b
    i = 2
    while i * i <= m:
        while m % i == 0:
            factors[i] = factors.get(i, 0) + 1
            m = m // i
        i += 1
    if m > 1:
        factors[m] = 1

    min_z = float('inf')
    for p, e in factors.items():
        def count_exponents(x):
            if x == 0:
                return 0
            res = 0
            current = p
            while current <= x:
                res += x // current
                current *= p
            return res
        exp_n = count_exponents(n)
        exp_k = count_exponents(k)
        exp_nk = count_exponents(n - k)
        exponent_in_C = exp_n - exp_k - exp_nk
        z = exponent_in_C // e
        if z < min_z:
            min_z = z
    return min_z if min_z != float('inf') else 0

def lucky_numbers(limit):
    if type(limit) is not int:
        raise ValueError()
    if not (0 <= limit <= 10**5):
        raise ValueError()
    if limit < 1:
        return []
    current_list = list(range(1, limit + 1, 2))
    step = 1
    while step < len(current_list):
        m = current_list[step]
        current_list = [x for i, x in enumerate(current_list) if (i + 1) % m != 0]
        step += 1
    return current_list

