def consecutive_sums(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1 or n > 10**12:
        raise ValueError
    m = 2 * n
    factors = factorize(m)
    divisors = generate_divisors(factors)
    res = []
    for k in divisors:
        if k < 2:
            continue
        m_val = m // k
        if k % 2 == 1:
            valid = True
        else:
            if m_val % 2 == 1:
                valid = True
            else:
                valid = False
        if valid and m_val > k:
            a = (m_val - k + 1) // 2
            b = a + k - 1
            res.append((a, b))
    res.sort()
    return res

def count_consecutive_sums(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1 or n > 10**12:
        raise ValueError
    m = n
    while m % 2 == 0:
        m //= 2
    if m == 1:
        return 0
    factors = factorize(m)
    count = 1
    for exp in factors.values():
        count *= (exp + 1)
    return count - 1

def factorize(m):
    factors = {}
    while m % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        m //= 2
    i = 3
    while i * i <= m:
        while m % i == 0:
            factors[i] = factors.get(i, 0) + 1
            m //= i
        i += 2
    if m > 1:
        factors[m] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for prime, exp in factors.items():
        current_length = len(divisors)
        for e in range(1, exp + 1):
            p_power = prime ** e
            for i in range(current_length):
                divisors.append(divisors[i] * p_power)
    return divisors

