from collections import deque

def lca_answers(parent, queries):
    n = len(parent)
    if n == 0:
        raise ValueError

    for p in parent:
        if not isinstance(p, int):
            raise ValueError
        if isinstance(p, bool):
            raise ValueError

    roots = [i for i, p in enumerate(parent) if p == -1]
    if len(roots) != 1:
        raise ValueError
    root = roots[0]

    for i, p in enumerate(parent):
        if p == -1:
            continue
        if p < 0 or p >= n:
            raise ValueError

    children = [[] for _ in range(n)]
    for v in range(n):
        if parent[v] != -1:
            children[parent[v]].append(v)

    depth = [0] * n
    q = deque([root])
    while q:
        node = q.popleft()
        for child in children[node]:
            depth[child] = depth[node] + 1
            q.append(child)

    max_level = 15
    lift = [[-1] * n for _ in range(max_level)]
    for v in range(n):
        lift[0][v] = parent[v] if parent[v] != -1 else -1

    for j in range(1, max_level):
        for v in range(n):
            if lift[j-1][v] != -1:
                lift[j][v] = lift[j-1][lift[j-1][v]]
            else:
                lift[j][v] = -1

    result = []
    for q in queries:
