            raise ValueError
        u, v = q
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError
        if isinstance(u, bool) or isinstance(v, bool):
            raise ValueError
        if u < 0 or u >= n or v < 0 or v >= n:
