from collections import deque

def maze_steps(grid):
    if not grid:
        raise ValueError
    rows = len(grid)
    if not (1 <= rows <= 30):
        raise ValueError
    cols = len(grid[0])
    if not (1 <= cols <= 30):
        raise ValueError
    for row in grid:
        if len(row) != cols:
            raise ValueError
    allowed = {'#', '.', 'S', 'E', 'a', 'b', 'c', 'd', 'A', 'B', 'C', 'D'}
    count_S = 0
    count_E = 0
    for i in range(rows):
        for j in range(cols):
            c = grid[i][j]
            if c not in allowed:
                raise ValueError
            if c == 'S':
                count_S += 1
            elif c == 'E':
                count_E += 1
    if count_S != 1 or count_E != 1:
        raise ValueError

    start = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
                break
        if start:
            break

    queue = deque()
    visited = set()
    queue.append((start[0], start[1], 0, 0))
    visited.add((start[0], start[1], 0))
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        row, col, keys, steps = queue.popleft()
        if grid[row][col] == 'E':
            return steps
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                cell = grid[new_row][new_col]
                if cell == '#':
                    continue
                if 'A' <= cell <= 'D':
                    key_bit = ord(cell.lower()) - ord('a')
                    if not (keys & (1 << key_bit)):
                        continue
                new_keys = keys
                if 'a' <= cell <= 'd':
                    key_bit = ord(cell) - ord('a')
                    new_keys = keys | (1 << key_bit)
                state = (new_row, new_col, new_keys)
                if state not in visited:
                    visited.add(state)
                    queue.append((new_row, new_col, new_keys, steps + 1))
    return -1

