        raise ValueError
    row_length = len(grid[0])
    for row in grid:
        if not isinstance(row, str) or len(row) != row_length:
            raise ValueError
    rows = len(grid)
    cols = row_length
    if rows < 1 or rows > 30 or cols < 1 or cols > 30:
        raise ValueError
    allowed_chars = set('#.SE')
    for c in 'abcdABCD':
        allowed_chars.add(c)
    count_S = 0
    count_E = 0
    start_row = start_col = -1
    for i in range(rows):
        for j in range(cols):
            c = grid[i][j]
            if c not in allowed_chars:
                raise ValueError
            if c == 'S':
                count_S += 1
                start_row, start_col = i, j
            if c == 'E':
                count_E += 1
    if count_S != 1 or count_E != 1:
        raise ValueError
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque()
    queue.append((start_row, start_col, 0, 0))
    visited.add((start_row, start_col, 0))
    while queue:
        r, c, mask, steps = queue.popleft()
        if grid[r][c] == 'E':
            return steps
        for dr, dc in directions:
            nr = r + dr
            nc = c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == '#':
                    continue
                if 'A' <= cell <= 'D':
                    key_bit = ord(cell.lower()) - ord('a')
                    if not (mask & (1 << key_bit)):
                        continue
                new_mask = mask
                if 'a' <= cell <= 'd':
                    key_bit = ord(cell) - ord('a')
                    new_mask = mask | (1 << key_bit)
                state = (nr, nc, new_mask)
                if state not in visited:
                    visited.add(state)
                    queue.append((nr, nc, new_mask, steps + 1))
    return -1

import re

def satisfiable(constraints):
    if not isinstance(constraints, list):
        raise ValueError
    equalities = []
    disequalities = []
    variables_set = set()
    for c in constraints:
        if not isinstance(c, str):
            raise ValueError
        if not re.fullmatch(r'([a-z][a-z0-9]{0,7})(==|!=)([a-z][a-z0-9]{0,7})', c):
            raise ValueError
        if '==' in c:
            x, y = c.split('==')
            equalities.append((x, y))
        else:
            x, y = c.split('!=')
            disequalities.append((x, y))
        variables_set.add(x)
        variables_set.add(y)
    if not constraints:
        return True
    parent = {}
    rank = {}

    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(node1, node2):
        root1 = find(node1)
        root2 = find(node2)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            else:
                parent[root1] = root2
                if rank[root1] == rank[root2]:
                    rank[root2] += 1

    for var in variables_set:
        parent[var] = var
        rank[var] = 0
    for x, y in equalities:
        union(x, y)
    for x, y in disequalities:
        if x == y:
            return False
        if find(x) == find(y):
            return False
    return True

def eq_classes(constraints):
    if not satisfiable(constraints):
        return None
    variables_set = set()
    equalities = []
    for c in constraints:
        if '==' in c:
            x, y = c.split('==')
            equalities.append((x, y))
        else:
            x, y = c.split('!=')
        variables_set.add(x)
        variables_set.add(y)
    if not variables_set:
        return []
    parent = {}
    rank = {}

    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(node1, node2):
        root1 = find(node1)
        root2 = find(node2)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            else:
                parent[root1] = root2
                if rank[root1] == rank[root2]:
                    rank[root2] += 1

    for var in variables_set:
        parent[var] = var
        rank[var] = 0
    for x, y in equalities:
        union(x, y)
    classes = {}
    for var in variables_set:
        root = find(var)
        if root not in classes:
            classes[root] = []
        classes[root].append(var)
    for cls in classes.values():
        cls.sort()
    sorted_classes = sorted(classes.values(), key=lambda x: x[0])
    return sorted_classes

def rho_shapes(f):
    if not isinstance(f, list):
        raise ValueError
    n = len(f)
    if n == 0:
        raise ValueError
    for x in f:
        if type(x) is not int:
            raise ValueError
        if not (0 <= x < n):
            raise ValueError
    visited = [False] * n
    result = [(0, 0)] * n
    for v in range(n):
        if not visited[v]:
            current_dict = {}
            path = []
            current = v
            while True:
                if current in current_dict:
                    cycle_start = current_dict[current]
                    cycle_length = len(path) - cycle_start
                    for i in range(cycle_start, len(path)):
                        node = path[i]
                        result[node] = (0, cycle_length)
                    for i in range(cycle_start - 1, -1, -1):
                        result[path[i]] = (result[path[i + 1]][0] + 1, cycle_length)
                    for node in path:
                        visited[node] = True
                    break
                if visited[current]:
                    tail_of_next = result[current][0]
                    cycle_length_next = result[current][1]
                    for i in reversed(range(len(path))):
                        steps = len(path) - i
                        result[path[i]] = (steps + tail_of_next, cycle_length_next)
                    for node in path:
                        visited[node] = True
                    break
                current_dict[current] = len(path)
                path.append(current)
                current = f[current]
    return result

