def rdp_simplify(points, eps):
    if not isinstance(points, list):
        raise ValueError
    if len(points) > 500:
        raise ValueError
    for p in points:
        if not (isinstance(p, (tuple, list)) and len(p) == 2):
            raise ValueError
        x, y = p
        if isinstance(x, bool) or isinstance(y, bool):
            raise ValueError
        if not isinstance(x, int) or not isinstance(y, int):
            raise ValueError
        if abs(x) > 10**6 or abs(y) > 10**6:
            raise ValueError
    if not isinstance(eps, int) or eps < 0:
        raise ValueError

    len_points = len(points)
    if len_points == 0:
        return []
    if len_points == 1:
        return [tuple(points[0])]
    if len_points == 2:
        return [tuple(points[0]), tuple(points[1])]

    stack = [(0, len_points - 1)]
    kept = [False] * len_points
    kept[0] = True
    kept[-1] = True

    while stack:
        i, j = stack.pop()
        if j - i <= 1:
            continue
        A = points[i]
        B = points[j]
        dx = B[0] - A[0]
        dy = B[1] - A[1]
        ab2 = dx * dx + dy * dy
        max_dist_sq = 0
        max_k = -1

        for k in range(i + 1, j):
            P = points[k]
            x, y = P
            apx = x - A[0]
            apy = y - A[1]
            dot = apx * dx + apy * dy

            if ab2 == 0:
                current_cross_sq = apx * apx + apy * apy
            else:
                if dot <= 0:
                    current_dist_sq = apx * apx + apy * apy
                    current_cross_sq = current_dist_sq * ab2
                elif dot >= ab2:
                    current_dist_sq = (x - B[0])**2 + (y - B[1])**2
                    current_cross_sq = current_dist_sq * ab2
                else:
                    cross = apx * dy - apy * dx
                    current_cross_sq = cross * cross

            if (current_cross_sq > max_dist_sq) or (current_cross_sq == max_dist_sq and k < max_k):
                max_dist_sq = current_cross_sq
                max_k = k

        if ab2 == 0:
            if max_dist_sq > eps * eps:
                kept[max_k] = True
                stack.append((i, max_k))
                stack.append((max_k, j))
        else:
            if max_dist_sq > (eps * eps) * ab2:
                kept[max_k] = True
                stack.append((i, max_k))
                stack.append((max_k, j))

    return [tuple(points[i]) for i in range(len_points) if kept[i]]

