def polar_sort(points, origin):
    # Validate origin
    if not (isinstance(origin, (list, tuple)) and len(origin) == 2):
        raise ValueError
    ox, oy = origin
    for coord in (ox, oy):
        if not (isinstance(coord, int) and type(coord) is int):
            raise ValueError
        if abs(coord) > 10**6:
            raise ValueError

    # Validate points
    validated_points = []
    for p in points:
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            raise ValueError
        x, y = p
        for coord in (x, y):
            if not (isinstance(coord, int) and type(coord) is int):
                raise ValueError
            if abs(coord) > 10**6:
                raise ValueError
        validated_points.append((x, y))

    origin_points = []
    non_origin = []
    for p in validated_points:
        if p[0] == ox and p[1] == oy:
            origin_points.append(p)
        else:
            non_origin.append(p)

    def compare(p1, p2):
        dx1, dy1 = p1[0] - ox, p1[1] - oy
        dx2, dy2 = p2[0] - ox, p2[1] - oy

        def is_upper(vec_x, vec_y):
            if vec_y > 0:
                return True
            elif vec_y == 0:
                return vec_x > 0
            else:
                return False

        u_upper = is_upper(dx1, dy1)
        v_upper = is_upper(dx2, dy2)

        if u_upper and not v_upper:
            return -1
        elif not u_upper and v_upper:
            return 1
        else:
            cross = dx1 * dy2 - dy1 * dx2
            if cross == 0:
                dist1 = dx1**2 + dy1**2
                dist2 = dx2**2 + dy2**2
                if dist1 < dist2:
                    return -1
                elif dist1 > dist2:
                    return 1
                else:
                    return 0
            else:
                return -1 if cross > 0 else 1

    sorted_non_origin = sorted(non_origin, key=functools.cmp_to_key(compare))
    return origin_points + sorted_non_origin

