        g = math.gcd(dx, dy)
        if g == 0:
            canonical = (0, 0)
        else:
            sign = 1 if g > 0 else -1
            reduced_dx = dx // g * sign
            reduced_dy = dy // g * sign
            # Ensure the direction is preserved by making sure the greatest non-zero coordinate is positive
