        current_term = 0
        for k in range(1, eggs + 1):
            if mid < k:
                current_term = 0
            elif k == 1:
                current_term = mid
            else:
                current_term = current_term * (mid - (k-1)) // k
            sum_val += current_term
            if sum_val >= floors:
                break
        if sum_val >= floors:
            high = mid
        else:
            low = mid + 1
    return low

def first_drop(eggs, floors):
    if not (type(eggs) is int and type(floors) is int):
        raise ValueError
    if not (1 <= eggs <= 64):
        raise ValueError
    if not (1 <= floors <= 10**18):
        raise ValueError
    t = min_drops(eggs, floors)
    sum_val = 0
    current_term = 0
    e = eggs - 1
    t_val = t - 1
    for k in range(1, e + 1):
        if t_val < k:
            current_term = 0
        elif k == 1:
            current_term = t_val
        else:
            current_term = current_term * (t_val - (k-1)) // k
        sum_val += current_term
    return sum_val + 1

def interleave_count(a, b, c):
    if not (isinstance(a, str) and isinstance(b, str) and isinstance(c, str)):
        raise ValueError
    len_a, len_b, len_c = len(a), len(b), len(c)
    if len_a > 300 or len_b > 300:
        raise ValueError
    if len_c != len_a + len_b:
        return 0
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]
    dp[0][0] = 1
    for i in range(len_a + 1):
        for j in range(len_b + 1):
            if i == 0 and j == 0:
                continue
            current_index = i + j - 1
            val = 0
            if i > 0 and a[i - 1] == c[current_index]:
                val += dp[i - 1][j]
            if j > 0 and b[j - 1] == c[current_index]:
                val += dp[i][j - 1]
            dp[i][j] = val
    return dp[len_a][len_b]


def interleave_labels(a, b, c):
    if not (isinstance(a, str) and isinstance(b, str) and isinstance(c, str)):
        raise ValueError
    len_a, len_b, len_c = len(a), len(b), len(c)
    if len_a > 300 or len_b > 300:
        raise ValueError
    if len_c != len_a + len_b:
        return None
    possible = [[False] * (len_b + 1) for _ in range(len_a + 1)]
    possible[len_a][len_b] = True
    for i in reversed(range(len_a + 1)):
        for j in reversed(range(len_b + 1)):
            if i == len_a and j == len_b:
                continue
            k = i + j
            if k >= len_c:
                possible[i][j] = False
                continue
            current_char = c[k]
            res = False
            if i < len_a and a[i] == current_char:
                res = possible[i + 1][j]
            if j < len_b and b[j] == current_char:
                res = res or possible[i][j + 1]
            possible[i][j] = res
    if not possible[0][0]:
        return None
    res = []
    i = j = 0
    while i < len_a or j < len_b:
        k = i + j
        current_char = c[k]
        take_a = False
        if i < len_a and a[i] == current_char and possible[i + 1][j]:
            take_a = True
        if take_a:
            res.append('A')
            i += 1
        else:
            if j < len_b and b[j] == current_char and possible[i][j + 1]:
                res.append('B')
                j += 1
            else:
                return None
    return ''.join(res)

