from collections import deque

def topple(grid):
    # Validate input
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError
    rows = len(grid)
    if not (1 <= rows <= 20):
        raise ValueError
    if rows == 0 or len(grid[0]) == 0:
        raise ValueError
    cols = len(grid[0])
    if not (1 <= cols <= 20):
        raise ValueError
    for row in grid:
        if not isinstance(row, list) or len(row) != cols:
            raise ValueError
        for cell in row:
            if isinstance(cell, bool):
                raise ValueError
            if not isinstance(cell, int):
                raise ValueError
            if not (0 <= cell <= 10**4):
                raise ValueError

    # Create a deep copy of the grid
    stable = [row.copy() for row in grid]
    queue = deque()
    # Initialize the queue with all unstable cells
    for i in range(rows):
        for j in range(cols):
            if stable[i][j] >= 4:
                queue.append((i, j))

    count = 0
    while queue:
        i, j = queue.popleft()
        current = stable[i][j]
        if current < 4:
            continue
        k = current // 4
        count += k
        stable[i][j] -= 4 * k
        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < rows and 0 <= nj < cols:
                stable[ni][nj] += k
                if stable[ni][nj] >= 4:
                    queue.append((ni, nj))

    return (stable, count)

def play_snake(height, width, food, moves):
    # Validate height and width
    if type(height) is not int or type(width) is not int:
        raise ValueError
    if not (1 <= height <= 50 and 1 <= width <= 50):
        raise ValueError

    # Validate food
    for cell in food:
        if not (isinstance(cell, (list, tuple)) and len(cell) == 2):
            raise ValueError
        row, col = cell
        if not (isinstance(row, int) and isinstance(col, int)):
            raise ValueError
        if not (0 <= row < height and 0 <= col < width):
            raise ValueError

    # Validate moves
    allowed_moves = {'U', 'D', 'L', 'R'}
    for move in moves:
        if move not in allowed_moves:
            raise ValueError

    # Initialize game state
    snake = [(0, 0)]
    score = 0
    steps = 0
    current_food_index = 0 if len(food) > 0 else -1

    for move in moves:
        head_row, head_col = snake[0]
        if move == 'U':
            new_row, new_col = head_row - 1, head_col
        elif move == 'D':
            new_row, new_col = head_row + 1, head_col
        elif move == 'L':
            new_row, new_col = head_row, head_col - 1
        else:  # 'R'
            new_row, new_col = head_row, head_col + 1

        # Check if new head is off the board
        if not (0 <= new_row < height and 0 <= new_col < width):
            break

        new_head = (new_row, new_col)

        # Determine current food
        current_food = food[current_food_index] if current_food_index < len(food) else None

        # Build new_snake
        if current_food is not None and new_head == current_food:
            new_snake = [new_head] + snake
        else:
            new_snake = [new_head] + snake[:-1]

        # Check collision with body
        if new_head in new_snake[1:]:
            break

        # Update game state
        snake = new_snake
        if current_food is not None and new_head == current_food:
            score += 1
            current_food_index += 1
        steps += 1

    return (score, steps)

