def realize_gains(trades, method):
    if method not in ('fifo', 'lifo'):
        raise ValueError("Invalid method")
    lots = []
    total_gain = 0
    for trade in trades:
        kind, qty, price = trade
        if kind not in ('buy', 'sell'):
            raise ValueError("Invalid trade kind")
        if not (isinstance(qty, int) and not isinstance(qty, bool)):
            raise ValueError("Invalid quantity")
        if qty < 1:
            raise ValueError("Quantity must be at least 1")
        if not (isinstance(price, int) and not isinstance(price, bool)):
            raise ValueError("Invalid price")
        if price < 0:
            raise ValueError("Price must be non-negative")
        if kind == 'buy':
            lots.append([qty, price])
        else:
            remaining = qty
            gain = 0
            if method == 'fifo':
                i = 0
                while remaining > 0 and i < len(lots):
                    lot = lots[i]
                    lot_qty = lot[0]
                    lot_price = lot[1]
                    if lot_qty <= remaining:
                        gain += lot_qty * (price - lot_price)
                        remaining -= lot_qty
                        del lots[i]
                    else:
                        gain += remaining * (price - lot_price)
                        lots[i][0] -= remaining
                        remaining = 0
                        break
                if remaining > 0:
                    raise ValueError("Not enough shares")
            else:
                i = len(lots) - 1
                while remaining > 0 and i >= 0:
                    lot = lots[i]
                    lot_qty = lot[0]
                    lot_price = lot[1]
                    if lot_qty <= remaining:
                        gain += lot_qty * (price - lot_price)
                        remaining -= lot_qty
                        del lots[i]
                    else:
                        gain += remaining * (price - lot_price)
                        lots[i][0] -= remaining
                        remaining = 0
                        break
                    i -= 1
                if remaining > 0:
                    raise ValueError("Not enough shares")
            total_gain += gain
    return (total_gain, [(q, p) for q, p in lots])

