def min_jumps(lengths):
    if not isinstance(lengths, list):
        raise ValueError
    n = len(lengths)
    if n < 1 or n > 10**5:
        raise ValueError
    for x in lengths:
        if type(x) is not int:
            raise ValueError
        if x < 0:
            raise ValueError
    if n == 1:
        return 0
    jumps = 0
    current_jump_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + lengths[i])
        if i == current_jump_end:
            jumps += 1
            current_jump_end = farthest
            if current_jump_end >= n - 1:
                break
    return jumps if current_jump_end >= n - 1 else -1

