            raise ValueError
    if n == 1:
        return 0
    jumps = 0
    current_end = 0
    current_far = 0
    for i in range(n):
        current_far = max(current_far, i + lengths[i])
        if i == current_end:
            jumps += 1
            current_end = current_far
            if current_end >= n - 1:
                return jumps
    return -1

def farthest_after(lengths, k):
    if not isinstance(lengths, list):
        raise ValueError
    n = len(lengths)
    if n == 0 or n > 10**5:
        raise ValueError
    for x in lengths:
        if type(x) is not int or x < 0:
            raise ValueError
    if type(k) is not int or k < 0:
        raise ValueError
    current_end = 0
    next_end = 0
    count = 0
    for i in range(n):
        if i > current_end:
            break
        next_end = max(next_end, i + lengths[i])
        if i == current_end:
            count += 1
            if count > k:
                break
            current_end = next_end
    return min(current_end, n - 1)

